INSERT INTO feature VALUES('unification','checking','Unification and index refinement',NULL,'partial','notable',NULL,'Unification at a scrutinee''s type refines the context by a match: the solution step replaces the variable side of an arm''s index equation by the other side, in the arm''s goal and in each later binder the arm reads, a binder of the recursion''s stage by its own transport along a set; the injectivity step splits an equation between two applications of one constructor into one path for each field, each ascribed its two sides so a later solution reads them; a clash as a refutation and a conversion failure as a refusal owed.','core-checker','corpus/model/universe/code-beside-value.gandr corpus/model/data/injective-index.gandr corpus/pathological/data/dependent-vectors.gandr corpus/pathological/data/dependent-bounds.gandr corpus/model/data/typed-evaluator.gandr','corpus/ledger/features/unification.gandr','#391');
